 var raw=wiki.getTiddlerText(name,""),obj;
 try{obj=JSON.parse(raw);}catch(_){return null;}
 if(!obj||obj.version!==1||(!Array.isArray(obj.parts)&&!Array.isArray(obj.scenes)))return null;
