  range.addEventListener("input",function(){pause();seek(Number(range.value));});controls.appendChild(range);controls.appendChild(readout);
  seek(0);
  if(host.getAttribute("data-autoplay")==="yes"&&!(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches))start();
 });
}
window.HUWikiCutOutSite={hydrate:hydrate};
})();
"},"$:/plugins/huwiki/site-publisher/cutout/viewer.css":{"title":"$:/plugins/huwiki/site-publisher/cutout/viewer.css","type":"text/css","text":"/* CutOut site reader, from OAuthLab CutOutSiteRuntime.js; self-contained. */
.huw-site-cutout{margin:1.2em auto;max-width:100%;min-width:0}
.huw-site-cutout svg{display:block;width:100%;height:auto;background:transparent}
.huw-cutout-controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:8px 0;font:13px/1.5 system-ui}
.huw-cutout-controls button{cursor:pointer;border:1px solid #b9c5d1;border-radius:6px;padding:6px 10px;background:#fff;color:#20374b;touch-action:manipulation;min-height:38px}
.huw-cutout-controls button:focus-visible{outline:2px solid #08785e;outline-offset:2px}
.huw-cutout-controls input[type=range]{flex:1;min-width:90px;max-width:280px;touch-action:pan-y}
.husp-site-image,.husp-site-media{margin:1em auto;max-width:100%}
.husp-site-image img{display:block;max-width:100%;height:auto;margin:auto}
.husp-site-media audio,.husp-site-media video{max-width:100%;width:min(100%,850px)}
.husp-site-media figcaption{font-size:.82em;color:#64716b;margin-top:7px}
"}}}
